//! Golden test replaying `tests/fixtures/factor_eval.tsv`.
//!
//! Generated by `tests/generators/generate_factor_eval.py` via pandas, scipy,
//! statsmodels and numpy. Replayed here with zero Python dependencies.

use std::collections::HashMap;
use std::path::PathBuf;

use phasor_factor::{Method, Panel, cs_ic, forward_returns, summarize, ts_ic, ts_rolling_ic};

fn parse_floats(s: &str) -> Vec<f64> {
    if s.is_empty() || s == "-" {
        Vec::new()
    } else {
        s.split(',')
            .map(|v| match v {
                "nan" => f64::NAN,
                "inf" => f64::INFINITY,
                "-inf" => f64::NEG_INFINITY,
                other => other
                    .parse()
                    .unwrap_or_else(|e| panic!("bad float {other:?}: {e}")),
            })
            .collect()
    }
}

fn parse_params(s: &str) -> HashMap<String, usize> {
    let mut map = HashMap::new();
    if s != "-" && !s.is_empty() {
        for part in s.split(',') {
            if let Some((k, v)) = part.split_once('=') {
                map.insert(k.trim().to_string(), v.trim().parse().expect("param usize"));
            }
        }
    }
    map
}

fn agree(a: f64, b: f64) -> bool {
    if a.is_nan() || b.is_nan() {
        return a.is_nan() && b.is_nan();
    }
    if a.is_infinite() || b.is_infinite() {
        #[allow(clippy::float_cmp, reason = "infinities agree exactly or not at all")]
        return a == b;
    }
    (a - b).abs() <= 1e-7 * a.abs().max(b.abs()).max(1.0)
}

#[test]
fn replay_golden_factor_eval() {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/factor_eval.tsv");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let header = lines.next().expect("header");
    assert_eq!(header, "case\top\tparams\tn_rows\tn_cols\tx\ty\texpected");

    let mut count = 0;
    for line in lines {
        count += 1;
        let cols: Vec<&str> = line.split('\t').collect();
        assert_eq!(cols.len(), 8, "line: {line}");
        let case = cols[0];
        let op = cols[1];
        let params = parse_params(cols[2]);
        let n_rows: usize = cols[3].parse().expect("n_rows");
        let n_cols: usize = cols[4].parse().expect("n_cols");
        let x_data = parse_floats(cols[5]);
        let y_data = parse_floats(cols[6]);
        let expected = parse_floats(cols[7]);

        let actual = match op {
            "forward_returns" => {
                let p = Panel::new(&x_data, n_rows, n_cols).expect("panel x");
                let h = params["h"];
                let lag = params["lag"];
                forward_returns(&p, h, lag).expect("forward_returns")
            }
            "cs_pearson" | "cs_spearman" => {
                let px = Panel::new(&x_data, n_rows, n_cols).expect("panel x");
                let py = Panel::new(&y_data, n_rows, n_cols).expect("panel y");
                let min_names = params["min"];
                let ic = cs_ic(&[px], &[py], min_names, 1).expect("cs_ic");
                let m = if op == "cs_pearson" {
                    Method::Pearson
                } else {
                    Method::Spearman
                };
                ic.series(m, 0, 0).to_vec()
            }
            "ts_pearson" | "ts_spearman" => {
                let px = Panel::new(&x_data, n_rows, n_cols).expect("panel x");
                let py = Panel::new(&y_data, n_rows, n_cols).expect("panel y");
                let min_periods = params["min"];
                let m = if op == "ts_pearson" {
                    Method::Pearson
                } else {
                    Method::Spearman
                };
                ts_ic(&px, &py, m, min_periods, 1).expect("ts_ic")
            }
            "rolling_pearson" | "rolling_spearman" => {
                let px = Panel::new(&x_data, n_rows, n_cols).expect("panel x");
                let py = Panel::new(&y_data, n_rows, n_cols).expect("panel y");
                let w = params["w"];
                let min_periods = params["min"];
                let m = if op == "rolling_pearson" {
                    Method::Pearson
                } else {
                    Method::Spearman
                };
                ts_rolling_ic(&px, &py, w, min_periods, m, 1).expect("ts_rolling_ic")
            }
            "summary" => {
                let lags = params["lags"];
                let s = summarize(&x_data, lags);
                vec![
                    s.mean, s.std, s.icir, s.t, s.t_nw, s.p_nw, s.hit, s.n as f64,
                ]
            }
            other => panic!("unknown op {other} in case {case}"),
        };

        assert_eq!(
            actual.len(),
            expected.len(),
            "case {case} ({op}): length mismatch actual {} vs expected {}",
            actual.len(),
            expected.len()
        );
        for (i, (&act, &exp)) in actual.iter().zip(&expected).enumerate() {
            assert!(
                agree(act, exp),
                "case {case} ({op}) index {i}: actual {act:?} ({act}) vs expected {exp:?} ({exp})"
            );
        }
    }
    assert!(count >= 40, "expected at least 40 cases, got {count}");
}
